+"use client";
+
+import React, { useState } from 'react';
+import styled from 'styled-components';
+import { ProjectEstimate } from '@/app/ai-estimate/types/projectEstimate';
+import Icon from './Icon';
+import Modal from '@/components/common/Modal';
+import { useToast } from '@/components/common/ToastProvider';
+import { useThemeStore } from '@/store/themeStore';
+
+const CardWrapper = styled.div`
+  background-color: #12091A;
+  border: 1px solid #2F2F38;
+  color: ${({ theme }) => theme.text};
+  border-radius: 12px;
+  overflow: hidden;
+  margin: 24px 0;
+  padding: 20px;
+`;
+
+const Header = styled.div`
+
+`;
+
+  const Flex = styled.div`
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  margin: 0 0 32px 0;
+`;
+
+const SubText = styled.p`
+  font-size: 12px;
+  color: ${({ theme }) => theme.subtleText};
+  margin: 0 0 4px 0;
+`;
+
+const Title = styled.h2`
+  font-size: 20px;
+font-style: normal;
+font-weight: 700;
+line-height: normal;
+`;
+
+
+const Right = styled.div`
+  display: flex;
+  align-items: center;
+  gap: 8px;
+`;
+
+const Price = styled.p`
+  font-size: 20px;
+font-style: normal;
+font-weight: 700;
+line-height: normal;
+letter-spacing: 0.4px;
+  margin: 0 0 8px 0;
+  
+  span {
+    font-size: 0.7em;
+    font-weight: normal;
+    color: ${({ theme }) => theme.subtleText};
+    margin-left: 8px;
+  }
+`;
+
+const Period = styled.p`
+  font-size: 16px;
+font-style: normal;
+font-weight: 700;
+line-height: normal;
+letter-spacing: 0.32px;
+  color: ${({ theme }) => theme.text};
+  margin: 0 0 24px 0;
+
+  .p {
+  font-size: 12px;
+font-style: normal;
+font-weight: 400;
+line-height: normal;
+letter-spacing: 0.24px;
+color: ${({ theme }) => theme.subtleText};
+}
+`;
+
+const ActionButtons = styled.div`
+
+  display: flex;
+  gap: 10px;
+  padding-top: 4px;
+  margin: 4px;
+`;
+
+const Line = styled.div`
+  border-left: 1px solid ${({ theme }) => theme.border};
+  `;
+
+const ActionButton = styled.button<{ primary?: boolean }>`
+  flex: 1;
+  padding: 12px;
+  border-radius: 8px;
+  border: none;
+  background-color: ${({ theme }) => theme.accent };
+  color: ${({ theme, primary }) => (primary ? (theme.body) : theme.text)};
+  font-family: Roboto;
+  font-size: 16px;
+  font-style: normal;
+  font-weight: 600;
+  line-height: 160%; 
+  letter-spacing: 0.28px;
+  cursor: pointer;
+  transition: all 0.2s ease;
+
+  &:hover {
+    opacity: 0.8;
+  }
+`;
+
+const ShareInput = styled.div`
+  display: flex;
+  gap: 8px;
+  margin-top: 8px;
+
+  input {
+    flex: 1;
+    height: 44px;
+    border-radius: 8px;
+    border: 1px solid #e5e7eb;
+    background: #f9fafb;
+    color: #111827;
+    padding: 0 12px;
+  }
+
+  button {
+    height: 44px;
+    padding: 0 14px;
+    border-radius: 8px;
+    background: #2E2E48;
+    color: white;
+    font-size: 14px;
+font-style: normal;
+font-weight: 400;
+line-height: 160%;
+letter-spacing: 0.32px;
+  }
+`;
+
+interface EstimateCardProps {
+  estimate: ProjectEstimate;
+}
+
+const MyEstimateCard: React.FC<EstimateCardProps> = ({ estimate }) => {
+  const [openShare, setOpenShare] = useState(false)
+  const { success } = useToast()
+  const { isDarkMode } = useThemeStore()
+
+  // estimated_period가 '30주'와 같은 문자열일 경우를 가정하고 숫자만 추출합니다.
+  const weekValue = parseInt(estimate.estimated_period);
+
+  // 1개월의 평균 주 수 (30.41일 / 7일)를 사용하여 개월 수를 계산하고 올림 처리합니다.
+  const weeksPerMonth = 4.345;
+  const monthValue = Math.ceil(weekValue / weeksPerMonth);
+
+  // 최종적으로 보여줄 기간 문자열을 생성합니다.
+  const displayPeriod = `(약 ${monthValue}개월)`;
+
+  const shareUrl = typeof window !== 'undefined' ? window.location.href + `?estimate=${encodeURIComponent(estimate.project_name)}` : ''
+
+  const handleCopy = async () => {
+    try {
+      await navigator.clipboard.writeText(shareUrl)
+      success('링크가 복사되었습니다.')
+    } catch {
+      // ignore
+    }
+  }
+
+  return (
+    <CardWrapper>
+      <Header>
+      <SubText>{estimate.created_at || '2025-08-23'}</SubText>
+
+        <Flex>
+        <Title>{estimate.project_name}</Title>
+        <Right>
+       
+        </Right>
+
+        </Flex>
+        {/* <Price>
+          KRW {estimate.total_price}
+          <span>(부가세 별도)</span>
+        </Price>
+        <Period>
+          <span style={{marginRight: '4px'}}>{estimate.estimated_period}</span>
+          <span className="p">{displayPeriod}</span>
+        </Period> */}
+        <ActionButtons>
+          <ActionButton>공유하기</ActionButton>
+          <ActionButton>견적 PDF 받기</ActionButton>
+        </ActionButtons>
+      </Header>
+
+      <Modal open={openShare} title="견적서 공유" onClose={() => setOpenShare(false)} width={520}>
+        <div style={{ color: '#A1A1AA', fontSize: 14, marginBottom: 32 }}>공유받은 사용자는 견적 내용을 확인할 수 있습니다.</div>
+        <ShareInput>
+          <input readOnly value={shareUrl} placeholder="https://aigocorp.com/id..." />
+          <button onClick={handleCopy}>링크복사</button>
+        </ShareInput>
+      </Modal>
+    </CardWrapper>
+  );
+};
+
+export default MyEstimateCard;

